mapper.select:
/* selectOrg - Lee JiSeob */
WITH T1 AS ( SELECT INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, (SELECT D.INST_NM FROM SAA000 D /* 기관코드 */ WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM, C.INST_TYPE_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_NM, (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_CODE, (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_NM, CASE WHEN C.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT, RGN_CD, (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, C##RG.DEC_B64(RPRSV_NM_ENCPT) AS RPRSV_NM, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, C##RG.DEC_B64(PIC_MBL_TELNO_ENCPT) AS PIC_MBL_TELNO, PIC_EML_ADDR_ENCPT, C##RG.DEC_B64(PIC_EML_ADDR_ENCPT) AS PIC_EML_ADDR, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT
FROM SAA000 C /* 기관코드 */
WHERE C.APRV_YN = 'Y'
AND C.INST_NO = #{INST_NO}
AND C.DEL_YN = 'N'
AND C.UNT_TASKWK_SE_CD = #{UNIT_SYSTEM}
AND C.UNT_TASKWK_SE_CD = #{UNIT_TASKWORK}
AND C.INST_TYPE_SE_CD = #{ORG_TYPE}
AND C.INST_NM LIKE '%' || #{ORG_NAME} || '%'
AND C.RGN_CD = #{RGN_CD}
/* 시도,시군구 센터들만 조회시 (app/itgcm/casemng/uneart/cnterSprtInsert.clx) 시군구센터지원등록*/
AND C.INST_TYPE_SE_CD IN ('5', '8')
/* 경찰청 또는 교육청 */ AND ( C.INST_NO IN ( SELECT E.INST_NO FROM SAA000 E /* 기관코드 */ START WITH E.INST_NO != #{UP_INST_NO} AND E.UP_INST_NO = #{UP_INST_NO} CONNECT BY PRIOR E.INST_NO = E.UP_INST_NO ) OR C.INST_NO = #{UP_INST_NO} )
AND C.INST_NO IN ( SELECT E.INST_NO FROM SAA000 E /* 기관코드 */ START WITH E.INST_NO != #{UP_INST_NO} AND E.UP_INST_NO = #{UP_INST_NO} CONNECT BY PRIOR E.INST_NO = E.UP_INST_NO )
AND C.RSFR_INST_YN = 'Y'
AND C.RSFR_INST_YN = 'N'
)
SELECT
INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, UP_INST_NM, INST_TYPE_SE_CD, INST_TYPE_NM, UNIT_CODE, 1 AS UNIT_COUNT, UNIT_NM, UNIT_COUNT, RGN_CD, ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, RPRSV_NM, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, PIC_MBL_TELNO, PIC_EML_ADDR_ENCPT, PIC_EML_ADDR, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT
FROM T1
AND ENG_CTPV_NM = #{ENG_CTPV_NM}
/* START WITH UP_INST_NO = 0 */ /* CONNECT BY PRIOR INST_NO = UP_INST_NO */
/* ORDER SIBLINGS BY */
ORDER BY /* CASE INST_TYPE_SE_CD WHEN 1 THEN 1 ELSE 2 END, UNIT_NM, INST_NM */ CASE TO_NUMBER(INST_TYPE_SE_CD) WHEN 1 THEN 1 WHEN 4 THEN 2 WHEN 6 THEN 3 WHEN 5 THEN 4 ELSE 5 END, UNIT_NM, INST_NM

/* selectOrgCount - Lee JiSeob */
WITH T1 AS ( SELECT INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, (SELECT D.INST_NM FROM SAA000 D /* 기관코드 */ WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM, C.INST_TYPE_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_NM, (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_CODE, (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_NM, CASE WHEN C.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT, RGN_CD, (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, PIC_EML_ADDR_ENCPT, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT
FROM SAA000 C /* 기관코드 */
WHERE C.APRV_YN = 'Y'
AND C.INST_NO IN
#{item}
AND C.RSFR_INST_YN = 'Y'
AND C.DEL_YN = 'N'
AND C.UNT_TASKWK_SE_CD = #{UNIT_SYSTEM}
AND C.UNT_TASKWK_SE_CD = #{UNIT_TASKWORK}
AND C.INST_TYPE_SE_CD = #{ORG_TYPE}
AND C.INST_NM LIKE '%' || #{ORG_NAME} || '%'
AND C.RGN_CD = #{RGN_CD}
)
SELECT
COUNT(*) AS CNT
FROM T1
AND ENG_CTPV_NM = #{ENG_CTPV_NM}

/* selectOrgPaging - Lee JiSeob */
WITH T1 AS ( SELECT C.INST_NO, C.UNT_TASKWK_SE_CD, C.INST_NM, C.UP_INST_NO, (SELECT D.INST_NM FROM SAA000 D /* 기관코드 */ WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM, C.INST_TYPE_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_NM, (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_CODE, (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_NM, CASE WHEN C.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT, C.RGN_CD, (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS ENG_CTPV_NM, C.HPGE_URL_ADDR, C.MAIN_ENFC_INST_SE_CD, C.CTPV_CD, C.SGG_CD, C.BPLC_ZIP, C.BPLC_PST_ADDR, C.BPLC_DADDR, C.RPRSV_NM_ENCPT, C##RG.DEC_B64(C.RPRSV_NM_ENCPT) AS RPRSV_NM, C.RPRS_TELNO, C.RPRS_FXNO, C.APLCN_BGNG_YMD, C.APLCN_END_YMD, C.PIC_ENFSN_NO, C.PIC_NM_ENCPT, C.PIC_TELNO, C.PIC_MBL_TELNO_ENCPT, C##RG.DEC_B64(C.PIC_MBL_TELNO_ENCPT) AS PIC_MBL_TELNO, C.PIC_EML_ADDR_ENCPT, C##RG.DEC_B64(C.PIC_EML_ADDR_ENCPT) AS PIC_EML_ADDR, C.CNSGN_YMD, C.APLY_YMD, C.APLCNT_ID, C.APRV_YN, C.PRCS_YMD, C.AUTZR_ID, C.CTPV_LINK_PBADMS_RGN_CD, C.SGG_LINK_PBADMS_RGN_CD, C.EMD_LINK_PBADMS_RGN_CD, C.ORGNL_INST_NO, C.OFFCS_SGNNG_NO, C.ATFINO, C.DEL_YN, C.FRST_RGTR_ID, TO_CHAR(C.FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, C.LAST_MDFR_ID, TO_CHAR(C.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT, D.RJCT_CS_CN, (CASE D.APRV_STTS_SE_CD WHEN '1' THEN '1' WHEN '2' THEN '2' WHEN '3' THEN '3' ELSE '2' END) AS APRV_STTS_SE_CD
FROM SAA000 C /* 기관코드 */ LEFT JOIN (SELECT B.* , ROW_NUMBER() OVER(PARTITION BY B.INST_NO ORDER BY B.APLY_DT DESC) AS RN FROM SAA010 B
) AS D ON C.INST_NO = D.INST_NO AND D.RN = '1'
WHERE C.APRV_YN = 'Y'
AND C.INST_NO IN
#{item}
/* 연계인경우 교육부, 교육청은 리스트에 안나오도록 수정 */ AND C.UP_INST_NO != (SELECT INST_NO FROM SAA000 WHERE INST_NM = '교육부') AND C.INST_NM != '교육부'
/* 경찰청 연계의뢰인 경우 의뢰대상기관에서 경찰청은 안나오도록 수정 */ AND C.INST_NM NOT LIKE '%경찰%'
AND C.RSFR_INST_YN = 'Y'
AND C.DEL_YN = 'N'
AND C.UNT_TASKWK_SE_CD = #{UNIT_SYSTEM}
AND C.UNT_TASKWK_SE_CD = #{UNIT_TASKWORK}
AND C.INST_TYPE_SE_CD = #{ORG_TYPE}
AND C.INST_NM LIKE '%' || #{ORG_NAME} || '%'
AND C.RGN_CD = #{RGN_CD}
)
SELECT
INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, UP_INST_NM, INST_TYPE_SE_CD, INST_TYPE_NM, UNIT_CODE, 1 AS UNIT_COUNT, UNIT_NM, UNIT_COUNT, RGN_CD, ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, RPRSV_NM, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, PIC_MBL_TELNO, PIC_EML_ADDR_ENCPT, PIC_EML_ADDR, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT, RJCT_CS_CN, APRV_STTS_SE_CD
FROM T1
AND ENG_CTPV_NM = #{ENG_CTPV_NM}
ORDER BY CASE INST_TYPE_SE_CD WHEN 1 THEN 1 ELSE 2 END, UNIT_NM, INST_NM
OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

/* selectInstituteType - Lee JiSeob */
SELECT TYPE_ID, TYPE_NAME, TYPE_LEVEL, WORKING_AGENCY_YN, LIST_ORDER
FROM INSTITUTE_TYPE ORDER BY LIST_ORDER, TYPE_ID

/* selectOrgRestArea - Lee Ji Seob */
SELECT INST_NO, RPRSV_NM_ENCPT, JIKIMI_MBR_YN, JIKIMI_JOIN_YMD, ENTRNC_PSNCPA_CNT, SXDC_SE_CD, PRTCTN_PRD_SE_CD, BGNG_AGE, END_AGE, SUPRT_RCIPT_FOIS_GRP_NM, SUPRT_RCIPT_FOIS_REG_NO, SUPRT_RCIPT_FOIS_ADDR, OFFCS_IMAGE_ATFINO, WLFAR_FCLTY_CEOFDE_ATFINO, INST_OFCL_NM, STYNG_TYPE_SE_CD, TAXOFC_CEOFID_NO, IAGRTE_YMD, HPGE_URL_ADDR, SHELTR_PRTCTN_PRD_DTL_SE_CD, SUPRT_RCIPT_FOIS_ZIP, SUPRT_RCIPT_FOIS_DADDR, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT
FROM SAA050 /* 쉼터정보 */
WHERE INST_NO = #{instNo}

/* selectNewInstituteList - Lee Ji Seob modify Taesoo Song 20230426*/
C.INST_NO, TO_CHAR(D.APLY_DT, 'YYYYMMDDHH24MISS') AS APLY_DT, C.UNT_TASKWK_SE_CD, C.INST_NM, C.UP_INST_NO, (SELECT D.INST_NM FROM SAA000 D WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM, C.INST_TYPE_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D /* 공통코드 값 */ WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_SE_NM, C.RGN_CD, (SELECT D.CTPV_NM || '-' || D.SGG_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS RGN_NM, C.HPGE_URL_ADDR, C.MAIN_ENFC_INST_SE_CD, C.CTPV_CD, C.SGG_CD, C.BPLC_ZIP, C.BPLC_PST_ADDR, C.BPLC_DADDR, C.RPRSV_NM_ENCPT, C##RG.DEC_B64(C.RPRSV_NM_ENCPT) AS RPRSV_NM, C##RG.DEC_B64(C.RPRSV_NM_ENCPT) AS RPRSV_NM_MASKING, C.RPRS_TELNO, C.RPRS_FXNO, C.APLCN_BGNG_YMD, C.APLCN_END_YMD, C.PIC_NM_ENCPT, C##RG.DEC_B64(C.PIC_NM_ENCPT) AS PIC_NM, C##RG.DEC_B64(C.PIC_NM_ENCPT) AS PIC_NM_MASKING, C.PIC_TELNO, C.PIC_MBL_TELNO_ENCPT, C.CNSGN_YMD, C.APLY_YMD, C.APLCNT_ID, C.APRV_YN, C.RJCT_CS_CN, C.PRCS_YMD, C.AUTZR_ID, C##RG.SA_FN_GET_NAME(C.AUTZR_ID) AS AUTZR_NM, C.ATFINO, C.DEL_YN, C.FRST_RGTR_ID, C##RG.DEC_B64(C##RG.SA_FN_GET_NAME(C.FRST_RGTR_ID)) AS FRST_RGTR_NM, TO_CHAR(C.FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, C.LAST_MDFR_ID, TO_CHAR(C.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT, C.CTPV_LINK_PBADMS_RGN_CD, C.SGG_LINK_PBADMS_RGN_CD, C.EMD_LINK_PBADMS_RGN_CD, C.PIC_EML_ADDR_ENCPT, C.OFFCS_SGNNG_NO, C.PIC_ENFSN_NO, C.ORGNL_INST_NO
FROM SAA000 C /* 통합기관 */ LEFT JOIN SAA010 D ON C.INST_NO = D.INST_NO WHERE D.APRV_STTS_SE_CD = #{APRV_STTS_SE_CD}
AND ( C.UP_INST_NO = #{APRV_INST_NO} /* 상위기관번호 */ OR C.UP_APRV_INST_NO = #{APRV_INST_NO} /* 상위승인기관번호 */
OR C.INST_NO = #{OGDP_INST_NO} /* 소속기관번호 */
)
AND C.RSFR_INST_YN = 'Y'
AND C.INST_NM LIKE '%' || #{INST_NM} || '%'
AND C.INST_TYPE_SE_CD = #{INST_TYPE_SE_CD}
AND C.RGN_CD = #{RGN_CD}
AND C.RPRSV_NM_ENCPT = C##RG.ENC_B64(#{RPRSV_NM})
AND C.PIC_NM_ENCPT = C##RG.ENC_B64(#{PIC_NM})
AND C.FRST_REG_DT >= TO_DATE(#{REG_DT_FROM} || '000000', 'YYYYMMDDHH24MISS')
AND C.FRST_REG_DT <= TO_DATE(#{REG_DT_TO} || '235959', 'YYYYMMDDHH24MISS')
ORDER BY C.FRST_REG_DT DESC, C.INST_NO DESC

/* ResrceSelectOrg - Choi Doo il */
WITH T1 AS ( SELECT C.INST_NO AS INST_NO , C.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD , C.INST_NM AS INST_NM , C.UP_INST_NO AS UP_INST_NO , (SELECT D.INST_NM FROM SAA000 D /* 기관코드 */ WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM , C.INST_TYPE_SE_CD AS INST_TYPE_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_NM , (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_CODE , (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_NM , CASE WHEN C.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT , C.RGN_CD AS RGN_CD , (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS ENG_CTPV_NM , C.HPGE_URL_ADDR AS HPGE_URL_ADDR , C.MAIN_ENFC_INST_SE_CD AS MAIN_ENFC_INST_SE_CD , C.CTPV_CD AS CTPV_CD , (SELECT D.CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS CTPV_NM , C.SGG_CD , (SELECT D.SGG_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS SGG_NM , C.BPLC_ZIP AS BPLC_ZIP , C.BPLC_PST_ADDR AS BPLC_PST_ADDR , C.BPLC_DADDR AS BPLC_DADDR , C.RPRSV_NM_ENCPT AS RPRSV_NM_ENCPT , C##RG.DEC_B64(C.RPRSV_NM_ENCPT) AS RPRSV_NM , C.RPRS_TELNO AS RPRS_TELNO , C.RPRS_FXNO AS RPRS_FXNO , C.APLCN_BGNG_YMD AS APLCN_BGNG_YMD /* 적용시작일자 */ , C.APLCN_END_YMD AS APLCN_END_YMD /* 적용종료일자 */ , C.PIC_ENFSN_NO AS PIC_ENFSN_NO , C.PIC_NM_ENCPT AS PIC_NM_ENCPT , C.PIC_TELNO AS PIC_TELNO , C.PIC_MBL_TELNO_ENCPT AS PIC_MBL_TELNO_ENCPT , C##RG.DEC_B64(C.PIC_MBL_TELNO_ENCPT) AS PIC_MBL_TELNO , C.PIC_EML_ADDR_ENCPT AS PIC_EML_ADDR_ENCPT , C##RG.DEC_B64(C.PIC_EML_ADDR_ENCPT) AS PIC_EML_ADDR , C.CNSGN_YMD AS CNSGN_YMD , C.APLY_YMD AS APLY_YMD , C.APLCNT_ID AS APLCNT_ID , C.APRV_YN AS APRV_YN , C.RJCT_CS_CN AS RJCT_CS_CN , C.PRCS_YMD AS PRCS_YMD , C.AUTZR_ID AS AUTZR_ID , C.CTPV_LINK_PBADMS_RGN_CD AS CTPV_LINK_PBADMS_RGN_CD , C.SGG_LINK_PBADMS_RGN_CD AS SGG_LINK_PBADMS_RGN_CD , C.EMD_LINK_PBADMS_RGN_CD AS EMD_LINK_PBADMS_RGN_CD , C.ORGNL_INST_NO AS ORGNL_INST_NO , C.OFFCS_SGNNG_NO AS OFFCS_SGNNG_NO , C.ATFINO AS ATFINO , C.CNTER_PRECON_WRT_YN AS CNTER_PRECON_WRT_YN , C.RSFR_INST_YN AS RSFR_INST_YN /* 자원제공주체여부 */ , C.DEL_YN AS DEL_YN , '' AS BRNO /* 사업자등록번호(순수자원주체SDA600)*/ , '' AS RSFR_MBY_SE_CD /* 자원제공주체구분코드(순수자원주체SDA600)*/ , '' AS BZMN_SE_CD /* 사업자구분코드(순수자원주체SDA600)*/ , '' AS FCLTY_INST_SE_CD /* 시설기관구분코드(순수자원주체SDA600)*/ , '' AS PVSN_MBY_DSCRP_CN /* 제공주체설명내용(순수자원주체SDA600)*/ , C.FRST_RGTR_ID AS FRST_RGTR_ID , TO_CHAR(C.FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT , C.LAST_MDFR_ID AS LAST_MDFR_ID , TO_CHAR(C.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT , '01' AS INFO_NO /* 기관SAA000*/ FROM SAA000 C /* 기관코드 */ WHERE C.APRV_YN = 'Y' AND C.RSFR_INST_YN = 'Y' AND C.DEL_YN = 'N' AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN NVL(C.APLCN_BGNG_YMD,'19000101') AND NVL(C.APLCN_END_YMD,'99991231')
), T2 AS ( SELECT T2.INST_NO AS INST_NO /* 기관번호*/ , T2.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드*/ , T2.INST_NM AS INST_NM /* 기관명*/ , '' AS UP_INST_NO /* 상위기관번호(기관SAA000)*/ , '' AS UP_INST_NM /* 상위기관명(기관SAA000)*/ , T2.INST_TYPE_SE_CD AS INST_TYPE_SE_CD /* 기관유형구분코드*/ ,(SELECT X.CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND X.CMMNS_CD_VALUE = T2.INST_TYPE_SE_CD) AS INST_TYPE_NM , (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = T2.UNT_TASKWK_SE_CD) AS UNIT_CODE , (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = T2.UNT_TASKWK_SE_CD) AS UNIT_NM , CASE WHEN T2.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT , T2.RGN_CD AS RGN_CD /* 지역코드*/ , (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = T2.RGN_CD) AS ENG_CTPV_NM , '' AS HPGE_URL_ADDR /* 홈페이지주소(기관SAA000)*/ , '' AS MAIN_ENFC_INST_SE_CD /* 주요시행기관구분코드 (기관SAA000)*/ , '' AS CTPV_CD /* 시도코드(기관SAA000)*/ , (SELECT D.CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = T2.RGN_CD) AS CTPV_NM , '' AS SGG_CD /* 시군구코드(기관SAA000)*/ , (SELECT D.SGG_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = T2.RGN_CD) AS SGG_NM , T2.BPLC_ZIP AS BPLC_ZIP /* 사업장우편번호*/ , T2.BPLC_PST_ADDR AS BPLC_PST_ADDR /* 사업장우편주소*/ , T2.BPLC_DADDR AS BPLC_DADDR /* 사업장상세주소*/ , T2.RPRSV_NM_ENCPT AS RPRSV_NM_ENCPT /* 대표자명암호화*/ , C##RG.DEC_B64(T2.RPRSV_NM_ENCPT) AS RPRSV_NM , T2.RPRS_TELNO AS RPRS_TELNO /* 대표전화번호*/ , '' AS RPRS_FXNO /* 대표팩스번호(기관SAA000)*/ , T2.APLCN_BGNG_YMD AS APLCN_BGNG_YMD /* 적용시작일자*/ , T2.APLCN_END_YMD AS APLCN_END_YMD /* 적용종료일자*/ , T2.PIC_ENFSN_NO AS PIC_ENFSN_NO /* 담당자종사자번호*/ , T2.PIC_NM_ENCPT AS PIC_NM_ENCPT /* 담당자명암호화*/ , T2.PIC_TELNO AS PIC_TELNO /* 담당자전화번호*/ , T2.PIC_MBL_TELNO_ENCPT AS PIC_MBL_TELNO_ENCPT /* 담당자휴대전화번호암호화*/ , C##RG.DEC_B64(T2.PIC_MBL_TELNO_ENCPT) AS PIC_MBL_TELNO , T2.PIC_EML_ADDR_ENCPT AS PIC_EML_ADDR_ENCPT /* 담당자이메일주소암호화*/ , C##RG.DEC_B64(T2.PIC_EML_ADDR_ENCPT) AS PIC_EML_ADDR , '' AS CNSGN_YMD /* 위탁일자(기관SAA000)*/ , T2.APLY_YMD AS APLY_YMD /* 신청일자*/ , T2.APLCNT_ID AS APLCNT_ID /* 신청자아이디*/ , T2.APRV_YN AS APRV_YN /* 승인여부*/ , T2.RJCT_CS_CN AS RJCT_CS_CN /* 반려사유내용*/ , T2.PRCS_YMD AS PRCS_YMD /* 처리일자*/ , T2.AUTZR_ID AS AUTZR_ID /* 승인자아이디*/ , '' AS CTPV_LINK_PBADMS_RGN_CD /* 시도연계행정지역코드(기관SAA000)*/ , T2.SGG_LINK_PBADMS_RGN_CD AS SGG_LINK_PBADMS_RGN_CD /* 시군구연계행정지역코드*/ , T2.EMD_LINK_PBADMS_RGN_CD AS EMD_LINK_PBADMS_RGN_CD /* 읍면동연계행정지역코드*/ , '' AS ORGNL_INST_NO /* 원본기관번호(기관SAA000)*/ , '' AS OFFCS_SGNNG_NO /* 직인서명번호(기관SAA000)*/ , T2.ATFINO AS ATFINO /* 첨부파일번호*/ , '' AS CNTER_PRECON_WRT_YN /* 센터현황작성여부(기관SAA000)*/ , '' AS RSFR_INST_YN /* 자원제공기관여부(기관SAA000)*/ , T2.DEL_YN AS DEL_YN /* 삭제여부*/ , T2.BRNO AS BRNO /* 사업자등록번호*/ , T2.RSFR_MBY_SE_CD AS RSFR_MBY_SE_CD /* 자원제공주체구분코드*/ , T2.BZMN_SE_CD AS BZMN_SE_CD /* 사업자구분코드*/ , T2.FCLTY_INST_SE_CD AS FCLTY_INST_SE_CD /* 시설기관구분코드*/ , T2.PVSN_MBY_DSCRP_CN AS PVSN_MBY_DSCRP_CN /* 제공주체설명내용*/ , T2.FRST_RGTR_ID AS FRST_RGTR_ID /* 최초등록자아이디*/ , TO_CHAR(T2.FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT /* 최초등록일시*/ , T2.LAST_MDFR_ID AS LAST_MDFR_ID /* 최종수정자아이디*/ , TO_CHAR(T2.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT /* 최종수정일시*/ , '02' AS INFO_NO /* 순수자원제공기관SDA600*/ FROM SDA600 T2 WHERE 1 = 1 AND T2.APRV_YN = 'Y' /* 승인여부*/ AND T2.DEL_YN = 'N' /* 삭제여부*/ AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN NVL(T2.APLCN_BGNG_YMD,'19000101') AND NVL(T2.APLCN_END_YMD,'99991231')
), RSFR_LIST AS (
SELECT T11.* FROM ( SELECT * FROM T1 UNION ALL SELECT * FROM T2 ) T11 WHERE 1 = 1
AND T11.UNT_TASKWK_SE_CD = #{UNIT_SYSTEM}
AND T11.UNT_TASKWK_SE_CD = #{UNIT_TASKWORK}
AND T11.INST_TYPE_SE_CD = #{ORG_TYPE}
AND T11.INST_NM LIKE '%' || #{ORG_NAME} || '%'
AND T11.RGN_CD = #{RGN_CD}
AND T11.RGN_CD LIKE #{CTPV_CD} || '%'
AND T11.RGN_CD = #{SGG_CD}
)
INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, UP_INST_NM, INST_TYPE_SE_CD, INST_TYPE_NM, UNIT_CODE, 1 AS UNIT_COUNT, UNIT_NM, UNIT_COUNT, RGN_CD, ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, CTPV_NM, SGG_CD, SGG_NM, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, RPRSV_NM, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, /* 적용시작일자 */ APLCN_END_YMD, /* 적용종료일자 */ PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, PIC_MBL_TELNO, PIC_EML_ADDR_ENCPT, PIC_EML_ADDR, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, RSFR_INST_YN, /* 자원제공주체여부 */ FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT, INFO_NO FROM RSFR_LIST
/* START WITH UP_INST_NO = 0 */ /* CONNECT BY PRIOR INST_NO = UP_INST_NO */
/* ORDER SIBLINGS BY */
ORDER BY CASE INST_TYPE_SE_CD WHEN 1 THEN 1 ELSE 2 END, UNIT_NM, INST_NM

/* selectOrgAuthryCount - Kang hwayoung - 권한별 기관 검색 */
WITH T1 AS ( SELECT INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, (SELECT D.INST_NM FROM SAA000 D /* 기관코드 */ WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM, C.INST_TYPE_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_NM, (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_CODE, (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_NM, CASE WHEN C.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT, RGN_CD, (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, PIC_EML_ADDR_ENCPT, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT
FROM SAA000 C /* 기관코드 */
WHERE C.APRV_YN = 'Y' /*기관유형구분코드중 추가값이 설정되어 있는 건들의 목록만 가져옴*/ AND C.INST_TYPE_SE_CD IN (SELECT D.CMMNS_CD_VALUE FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND ADDTNG_MNG_VALUE1 = 'Y' AND USE_YN = 'Y') AND C.DEL_YN = 'N'
/*20230126_강화영_권한 쿼리 시작*/
AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 단위업무구분코드
/*지역권한*/ AND C.INST_NO IN
#{item}
/*20230126_강화영_권한 쿼리 종료*/
AND C.CTPV_CD = #{CTPV_SE_CD} -- 시도코드
AND C.RGN_CD = #{RGN_CD} -- 시군구코드
AND C.INST_TYPE_SE_CD NOT IN (2,3) -- 기관유형
AND C.INST_TYPE_SE_CD = #{MULTI_ORG_TYPE} -- 기관유형
AND C.INST_TYPE_SE_CD = #{ORG_TYPE}
AND C.INST_NM LIKE '%' || #{ORG_NAME} || '%'
)
SELECT
COUNT(*) AS CNT
FROM T1

/* selectOrgAuthryPaging - Kang hwayoung - 권한별 기관 검색 */
WITH T1 AS ( SELECT INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, (SELECT D.INST_NM FROM SAA000 D /* 기관코드 */ WHERE D.INST_NO = C.UP_INST_NO) AS UP_INST_NM, C.INST_TYPE_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = C.INST_TYPE_SE_CD) AS INST_TYPE_NM, (SELECT F.CMMNS_CD_VALUE FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_CODE, (SELECT F.CMMNS_CD_VALUE_NM FROM SAC100 F WHERE F.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND F.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_NM, CASE WHEN C.UNT_TASKWK_SE_CD IS NULL THEN 0 ELSE 1 END AS UNIT_COUNT, RGN_CD, (SELECT D.ENG_CTPV_NM FROM SAA020 D /* 시군구코드 */ WHERE D.SGG_CD = C.RGN_CD) AS ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, C##RG.DEC_B64(RPRSV_NM_ENCPT) AS RPRSV_NM, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, C##RG.DEC_B64(PIC_MBL_TELNO_ENCPT) AS PIC_MBL_TELNO, PIC_EML_ADDR_ENCPT, C##RG.DEC_B64(PIC_EML_ADDR_ENCPT) AS PIC_EML_ADDR, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI') AS LAST_MDFCN_DT
FROM SAA000 C /* 기관코드 */
WHERE C.APRV_YN = 'Y' /*기관유형구분코드중 추가값이 설정되어 있는 건들의 목록만 가져옴*/ AND C.INST_TYPE_SE_CD IN (SELECT D.CMMNS_CD_VALUE FROM SAC100 D WHERE D.CMMNS_CD_ID = 'INST_TYPE_SE_CD' AND ADDTNG_MNG_VALUE1 = 'Y' AND USE_YN = 'Y') AND C.DEL_YN = 'N' AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN NVL(C.APLCN_BGNG_YMD,'19000101') AND NVL(C.APLCN_END_YMD,'99991231')
/*20230126_강화영_권한 쿼리 시작*/
AND C.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 단위업무구분코드
/*지역권한*/ AND C.INST_NO IN
#{item}
/*20230126_강화영_권한 쿼리 종료*/
AND C.CTPV_CD = #{CTPV_SE_CD} -- 시도코드
AND C.RGN_CD = #{RGN_CD} -- 시군구코드
AND C.INST_TYPE_SE_CD NOT IN (2,3) -- 기관유형
AND C.INST_TYPE_SE_CD = #{MULTI_ORG_TYPE} -- 기관유형
AND C.INST_TYPE_SE_CD = #{ORG_TYPE}
AND C.INST_NM LIKE '%' || #{ORG_NAME} || '%'
)
SELECT
INST_NO, UNT_TASKWK_SE_CD, INST_NM, UP_INST_NO, UP_INST_NM, INST_TYPE_SE_CD, INST_TYPE_NM, UNIT_CODE, 1 AS UNIT_COUNT, UNIT_NM, UNIT_COUNT, RGN_CD, ENG_CTPV_NM, HPGE_URL_ADDR, MAIN_ENFC_INST_SE_CD, CTPV_CD, SGG_CD, BPLC_ZIP, BPLC_PST_ADDR, BPLC_DADDR, RPRSV_NM_ENCPT, RPRS_TELNO, RPRS_FXNO, APLCN_BGNG_YMD, APLCN_END_YMD, PIC_ENFSN_NO, PIC_NM_ENCPT, PIC_TELNO, PIC_MBL_TELNO_ENCPT, PIC_EML_ADDR_ENCPT, CNSGN_YMD, APLY_YMD, APLCNT_ID, APRV_YN, RJCT_CS_CN, PRCS_YMD, AUTZR_ID, CTPV_LINK_PBADMS_RGN_CD, SGG_LINK_PBADMS_RGN_CD, EMD_LINK_PBADMS_RGN_CD, ORGNL_INST_NO, OFFCS_SGNNG_NO, ATFINO, DEL_YN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT
FROM T1
ORDER BY CASE INST_TYPE_SE_CD WHEN 1 THEN 1 ELSE 2 END, UNIT_NM, INST_NM
OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY
